[[nodiscard]] std::optional<std::int64_t> max_window_sum(std::span<const int> nums, std::ptrdiff_t k) {
  if (k < 1 || k > std::ssize(nums)) return std::nullopt;
  std::int64_t window = std::accumulate(nums.begin(), nums.begin() + k, std::int64_t{0});  // nums[0..k-1]
  std::int64_t best = window;
  for (std::ptrdiff_t right = k; right < std::ssize(nums); ++right) {
    window += nums[right];      // enters
    window -= nums[right - k];  // leaves
    best = std::max(best, window);
  }
  return best;
}

[[nodiscard]] std::string show(const std::optional<std::int64_t>& sum) {
  return sum ? std::to_string(*sum) : "no value";
}

int main() {
  const std::vector<int> a{2, 1, 5, 1, 3, 2};
  const std::vector<int> b{-3, -1, -2};
  const std::vector<int> c{1, 2};
  std::cout << show(max_window_sum(a, 3)) << ' ' << show(max_window_sum(b, 2)) << ' ' << show(max_window_sum(c, 3))
            << '\n';
}

