struct Tally {
  std::int64_t best = 0;
  std::int64_t additions = 0;  // element additions and subtractions
};

[[nodiscard]] Tally recompute(std::span<const int> nums, std::ptrdiff_t k) {
  Tally t;
  for (std::ptrdiff_t left = 0; left + k <= std::ssize(nums); ++left) {
    std::int64_t sum = 0;
    for (std::ptrdiff_t i = left; i < left + k; ++i) {
      sum += nums[i];
      ++t.additions;
    }
    t.best = left == 0 ? sum : std::max(t.best, sum);
  }
  return t;
}

[[nodiscard]] Tally slide(std::span<const int> nums, std::ptrdiff_t k) {
  Tally t;
  std::int64_t window = 0;
  for (std::ptrdiff_t i = 0; i < k; ++i) {
    window += nums[i];
    ++t.additions;
  }
  t.best = window;
  for (std::ptrdiff_t right = k; right < std::ssize(nums); ++right) {
    window += nums[right];
    window -= nums[right - k];
    t.additions += 2;
    t.best = std::max(t.best, window);
  }
  return t;
}

int main() {
  std::vector<int> readings(1000);
  for (std::ptrdiff_t i = 0; i < std::ssize(readings); ++i) readings[i] = static_cast<int>(i * 37 % 101) - 50;
  for (const Tally& t : {recompute(readings, 100), slide(readings, 100)})
    std::cout << std::format("best {}, {} additions\n", t.best, t.additions);
}

