#include <vector>

[[nodiscard]] std::ptrdiff_t longest_with_at_most(std::span<const int> ids, std::ptrdiff_t k) {
  if (k < 1) return 0;
  std::unordered_map<int, std::ptrdiff_t> in_window;  // id -> occurrences in ids[left..right]
  std::ptrdiff_t best = 0;
  std::ptrdiff_t left = 0;
  for (std::ptrdiff_t right = 0; right < std::ssize(ids); ++right) {
    ++in_window[ids[right]];
    while (std::ssize(in_window) > k) {
      const auto it = in_window.find(ids[left]);
      if (--it->second == 0) in_window.erase(it);  // keep size() equal to the number of distinct ids
      ++left;
    }
    best = std::max(best, right - left + 1);
  }
  return best;
}

int main() {
  const std::vector<int> ids{3, 1, 3, 2, 2, 3, 1};
  for (const std::ptrdiff_t k : {1, 2, 3}) std::cout << std::format("k = {}: {}\n", k, longest_with_at_most(ids, k));
  std::cout << std::format("empty: {}\n", longest_with_at_most(std::vector<int>{}, 2));
}

