#include <algorithm>
#include <array>
#include <cstddef>
#include <format>
#include <iostream>
#include <string_view>

[[nodiscard]] std::ptrdiff_t longest_unique(std::string_view s) {
  std::array<std::ptrdiff_t, 256> counts{};  // occurrences of each byte in s[left..right]
  const auto slot = [](char c) { return static_cast<unsigned char>(c); };  // char may be negative
  std::ptrdiff_t best = 0;
  std::ptrdiff_t left = 0;
  for (std::ptrdiff_t right = 0; right < std::ssize(s); ++right) {
    const unsigned char entering = slot(s[right]);
    ++counts[entering];
    while (counts[entering] > 1) {
      --counts[slot(s[left])];
      ++left;
    }
    best = std::max(best, right - left + 1);
  }
  return best;
}

[[nodiscard]] std::ptrdiff_t longest_unique_jump(std::string_view s) {
  std::array<std::ptrdiff_t, 256> after_last{};  // one past the last index of each byte; 0 if not seen
  std::ptrdiff_t best = 0;
  std::ptrdiff_t left = 0;
  for (std::ptrdiff_t right = 0; right < std::ssize(s); ++right) {
    const unsigned char entering = static_cast<unsigned char>(s[right]);
    left = std::max(left, after_last[entering]);  // never move left backwards
    after_last[entering] = right + 1;
    best = std::max(best, right - left + 1);
  }
  return best;
}

int main() {
  for (const std::string_view s : {"abcabcbb", "bbbbb", "pwwkew", "abba", ""})
    std::cout << std::format("\"{}\": {} {}\n", s, longest_unique(s), longest_unique_jump(s));
}

