[[nodiscard]] std::optional<std::ptrdiff_t> shortest_at_least(std::span<const int> nums, std::int64_t target) {
  std::optional<std::ptrdiff_t> best;
  std::int64_t window = 0;  // sum of nums[left..right]
  std::ptrdiff_t left = 0;
  for (std::ptrdiff_t right = 0; right < std::ssize(nums); ++right) {
    window += nums[right];
    while (left <= right && window >= target) {
      const std::ptrdiff_t length = right - left + 1;
      if (!best || length < *best) best = length;
      window -= nums[left];
      ++left;
    }
  }
  return best;
}

[[nodiscard]] std::string show(const std::optional<std::ptrdiff_t>& length) {
  return length ? std::to_string(*length) : "no value";
}

int main() {
  const std::vector<int> a{2, 3, 1, 2, 4, 3};
  const std::vector<int> b{1, 4, 4};
  const std::vector<int> c{1, 1, 1};
  const std::vector<int> none;
  std::cout << std::format("{} {} {}\n", show(shortest_at_least(a, 7)), show(shortest_at_least(b, 4)),
                           show(shortest_at_least(c, 11)));
  std::cout << std::format("target 0: {}, empty input: {}\n", show(shortest_at_least(a, 0)),
                           show(shortest_at_least(none, 1)));
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <vector>

[[nodiscard]] std::ptrdiff_t longest_ones(std::span<const int> bits, std::ptrdiff_t k) {
  if (k < 0) return 0;
  std::ptrdiff_t zeros = 0;  // zeros in bits[left..right]
  std::ptrdiff_t best = 0;
  std::ptrdiff_t left = 0;
  for (std::ptrdiff_t right = 0; right < std::ssize(bits); ++right) {
    if (bits[right] == 0) ++zeros;
    while (zeros > k) {
      if (bits[left] == 0) --zeros;
      ++left;
    }
    best = std::max(best, right - left + 1);
  }
  return best;
}

// Tries every run bits[first..last]: O(n²), for testing only.
[[nodiscard]] std::ptrdiff_t longest_ones_slow(std::span<const int> bits, std::ptrdiff_t k) {
  std::ptrdiff_t best = 0;
  for (std::ptrdiff_t first = 0; first < std::ssize(bits); ++first) {
    std::ptrdiff_t zeros = 0;
    for (std::ptrdiff_t last = first; last < std::ssize(bits); ++last) {
      if (bits[last] == 0) ++zeros;
      if (zeros <= k) best = std::max(best, last - first + 1);
    }
  }
  return best;
}

int main() {
  const std::vector<int> bits{1, 0, 1, 1, 0, 0, 1, 1, 1, 0, 1};
  for (const std::ptrdiff_t k : {0, 1, 2, 5})
    std::cout << std::format("k = {}: {} (slow {})\n", k, longest_ones(bits, k), longest_ones_slow(bits, k));
  const std::vector<int> zeros_only{0, 0, 0};
  std::cout << std::format("zeros only, k = 0: {}\n", longest_ones(zeros_only, 0));
}

