[[nodiscard]] std::ptrdiff_t longest_unique_with_if(std::string_view s) {
  std::array<std::ptrdiff_t, 256> counts{};
  const auto slot = [](char c) { return static_cast<unsigned char>(c); };
  std::ptrdiff_t best = 0;
  std::ptrdiff_t left = 0;
  for (std::ptrdiff_t right = 0; right < std::ssize(s); ++right) {
    const unsigned char entering = slot(s[right]);
    ++counts[entering];
    if (counts[entering] > 1) {  // wrong: one removal may not be enough
      --counts[slot(s[left])];
      ++left;
    }
    best = std::max(best, right - left + 1);
  }
  return best;
}

