  for (const std::string_view s : {"abcabcbb", "abba"}) std::cout << std::format("\"{}\": {}\n", s, longest_unique_with_if(s));
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <string>
#include <vector>

[[nodiscard]] std::optional<std::ptrdiff_t> shortest_at_least(std::span<const int> nums, std::int64_t target) {
  std::optional<std::ptrdiff_t> best;
  std::int64_t window = 0;
  std::ptrdiff_t left = 0;
  for (std::ptrdiff_t right = 0; right < std::ssize(nums); ++right) {
    window += nums[right];
    while (left <= right && window >= target) {
      const std::ptrdiff_t length = right - left + 1;
      if (!best || length < *best) best = length;
      window -= nums[left];
      ++left;
    }
  }
  return best;
}

[[nodiscard]] std::optional<std::ptrdiff_t> shortest_by_trying_all(std::span<const int> nums, std::int64_t target) {
  std::optional<std::ptrdiff_t> best;
  for (std::ptrdiff_t first = 0; first < std::ssize(nums); ++first) {
    std::int64_t sum = 0;
    for (std::ptrdiff_t last = first; last < std::ssize(nums); ++last) {
      sum += nums[last];
      if (sum >= target && (!best || last - first + 1 < *best)) best = last - first + 1;
    }
  }
  return best;
}

[[nodiscard]] std::string show(const std::optional<std::ptrdiff_t>& length) {
  return length ? std::to_string(*length) : "no value";
}

int main() {
  const std::vector<int> nums{3, -2, 4};
  std::cout << std::format("window: {}, every subarray: {}\n", show(shortest_at_least(nums, 4)),
                           show(shortest_by_trying_all(nums, 4)));
}
